-- Referencia local de las cuatro tablas previas a supabase_migration.sql.
-- Metadatos consultados sin filas del proyecto SIDE; no aplicar en producción.
begin;
create table public.empresas (id bigint generated by default as identity primary key,nombre_legal text not null,nombre_comercial text not null,caja_inicial numeric(12,2) not null default 100000,caja_actual numeric(12,2) not null default 100000,ciclo_actual integer not null default 1,reputacion numeric(5,2) not null default 80,created_at timestamptz not null default now());
create table public.decisiones_catalogo (id serial primary key,categoria text not null,categoria_nombre text not null,decision_id text not null unique,decision_nombre text not null,tipo text not null,es_recurrente boolean not null default false,es_obligatoria boolean not null default false,costo_base numeric(12,2),descripcion text,activo boolean not null default true,created_at timestamptz not null default now(),unique(categoria,decision_id));
create table public.decisiones_opciones (id serial primary key,decision_id integer not null references public.decisiones_catalogo(id) on delete cascade,opcion_id text not null,etiqueta text not null,descripcion text,costo numeric(12,2) not null default 0,capacidad_diaria integer,tasa_liquidacion numeric(5,2),canal text,distrito text,demanda_factor numeric(5,2),compromiso_ciclos integer,activo boolean not null default true,created_at timestamptz not null default now(),constraint decisiones_opciones_decision_id_opcion_id_key unique(decision_id,opcion_id),constraint decisiones_opciones_decision_opcion_key unique(decision_id,opcion_id));
create table public.empresas_decisiones (id serial primary key,empresa_id integer not null references public.empresas(id) on delete cascade,ciclo integer not null,decision_id integer not null references public.decisiones_catalogo(id),opcion_id integer references public.decisiones_opciones(id),cantidad integer not null default 1,costo_total numeric(12,2) not null default 0,enviada boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint empresas_decisiones_empresa_ciclo_decision_key unique(empresa_id,ciclo,decision_id));
alter table public.empresas enable row level security;
alter table public.empresas_decisiones enable row level security;
alter table public.decisiones_catalogo enable row level security;
alter table public.decisiones_opciones enable row level security;
create policy "todos ven catálogo" on public.decisiones_catalogo for select to anon,authenticated using (true);
create policy "todos ven opciones" on public.decisiones_opciones for select to anon,authenticated using (true);
-- Las políticas del docente se crean cuando participantes.empresa_id esté disponible.
commit;
